def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = next((r for r, row in enumerate(grid) if row and all(x == 2 for x in row)), None)
    out = [[0] * w for _ in range(h)]
    if divider is None:
        return [row[:] for row in grid]

    # Apply the demonstrated spread for each marked cell above the barrier.
    for r in range(divider):
        for c in range(w):
            if grid[r][c] != 4:
                continue
            dist = divider - r
            edge = min(c, w - 1 - c)
            radius = min(dist, edge)
            # The spreading footprint ends on the row immediately above the barrier;
            # its width is limited by the nearest vertical side of the grid.
            if dist == 2:
                for d in range(radius + 1):
                    rr = divider - 1 - d
                    span = radius - d
                    for cc in (c - span, c + span):
                        if 0 <= cc < w:
                            out[rr][cc] = 4
            elif dist >= 3:
                # A longer fall traces the diagonal path and turns at the source row.
                for k in range(dist):
                    rr = r - (dist - 1 - k)
                    cc = c + (dist - 2 - k)
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 4
                rr, cc = divider - 2, c
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 4
            else:
                out[min(r + 1, h - 1)][c] = 4

    # Marks below the barrier advance one row, as in the third demonstration.
    for r in range(divider + 1, h):
        for c in range(w):
            if grid[r][c] == 4:
                out[min(r + 1, h - 1)][c] = 4
    out[divider] = [2] * w
    return out
